package com.example.yiyan;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import android.content.*;import java.util.*;
public class ManageQuotesActivity extends Activity{
 LinearLayout flow; ArrayList<EditText[]> rows=new ArrayList<>();
 public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_manage_quotes);flow=findViewById(R.id.quotes_flow);TextView title=new TextView(this);title.setText("一言管理 · 每句独立编辑");title.setTextSize(24);title.setTextColor(0xff24212a);title.setPadding(8,8,8,20);flow.addView(title);load();Button save=new Button(this);save.setText("保存全部修改");save.setOnClickListener(v->save());flow.addView(save);}
 void load(){android.content.SharedPreferences p=getSharedPreferences("settings",0);String saved=p.getString("editable_library","");ArrayList<String> lines=new ArrayList<>();if(saved.isEmpty())for(Quote q:QuoteLibrary.ALL)if(q.kind.equals("译写 / 意译"))lines.add(q.text+"|"+q.author+"|"+q.work);else lines.addAll(Arrays.asList(saved.split("\\n")));int n=1;for(String line:lines){String[] x=line.split("\\|",-1);if(x.length<3)continue;LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(18,14,18,14);card.setBackgroundColor(0xfffff9f0);TextView no=new TextView(this);no.setText("第 "+n+++" 句");no.setTextSize(15);no.setTextColor(0xff6750a4);card.addView(no);EditText t=field(x[0],"句子"),a=field(x[1],"作者"),w=field(x[2],"出处 / 作品");card.addView(t);card.addView(a);card.addView(w);flow.addView(card,new LinearLayout.LayoutParams(-1,-2));Space gap=new Space(this);flow.addView(gap,new LinearLayout.LayoutParams(1,12));rows.add(new EditText[]{t,a,w});}}
 EditText field(String text,String hint){EditText e=new EditText(this);e.setText(text);e.setHint(hint);e.setTextSize(15);e.setTextColor(0xff24212a);return e;}
 void save(){StringBuilder out=new StringBuilder();for(EditText[] r:rows){String t=r[0].getText().toString().trim(),a=r[1].getText().toString().trim(),w=r[2].getText().toString().trim();if(!t.isEmpty()&&!a.isEmpty()&&!w.isEmpty())out.append(t).append("|").append(a).append("|").append(w).append("\n");}getSharedPreferences("settings",0).edit().putString("editable_library",out.toString()).apply();android.util.Log.i("99YIYAN_LOG","用户保存瀑布流条目 "+rows.size());sendBroadcast(new Intent(QuoteWidgetProvider.ACTION).setPackage(getPackageName()));Toast.makeText(this,"已保存全部条目",Toast.LENGTH_SHORT).show();}
}
